def extract_sources():
    raw=base64.b64decode(SOURCE_BASE64,validate=True)
    if hashlib.sha256(raw).hexdigest()!=SOURCE_SHA256:raise ValueError('Embedded C35 ZIP digest differs')
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        names=z.namelist()
        if len(names)!=len(set(names)) or any(Path(n).is_absolute() or '..' in Path(n).parts or '\\' in n for n in names):raise ValueError('Unsafe source ZIP')
        manifest=json.loads(z.read('SOURCE_MANIFEST.json'))
        if set(names)!=set(manifest)|{'SOURCE_MANIFEST.json'}:raise ValueError('Source manifest coverage differs')
        for n,h in manifest.items():
            if hashlib.sha256(z.read(n)).hexdigest()!=h:raise ValueError('Source member differs: '+n)
        root=Path(tempfile.mkdtemp(prefix='gpt2_c35_source_'));z.extractall(root)
    return root

def start():
    root=extract_sources();names={p.stem for p in root.rglob('*.py')}
    old={n:sys.modules[n] for n in names if n in sys.modules};paths=sys.path[:]
    for n in names:sys.modules.pop(n,None)
    sys.path.insert(0,str(root))
    try:
        from launch_c35 import start as launch
        return launch(USE_GOOGLE_DRIVE,INPUT_ZIP)
    finally:
        for n in names:sys.modules.pop(n,None)
        sys.modules.update(old);sys.path[:]=paths

if __name__=='__main__':start()
